using Forge.LiveDirector.Authoring;
using Forge.Network.Operations;

namespace Forge.LiveDirector.Tests;

public sealed class LiveDirectorGroupProfileTests
{
    [Fact] public void R128_TriggerSelectionMoveAttackAndTravel_AreGoverned() { var p = LiveDirectorGroupProfile.CreateDefault(); Assert.Equal(2, p.TriggerEvents.Count); Assert.True(p.ScriptTracePreview && p.ViewportLasso && p.PermissionFilteredSelection); Assert.Equal(4, p.MovementFormations.Count); Assert.True(p.PathPreview && p.PartialFailureReport && p.RuntimePathAdapter); Assert.True(p.FactionSafetyAcknowledgement && p.RuntimeCombatAdapter); Assert.Equal(4, p.PlayerTravelModes.Count); Assert.True(p.PlayerConfirmation && p.PartyConsent && p.CameraTransitionAdapter); Assert.Empty(LiveDirectorGroupValidator.Validate(p)); }
    [Fact] public void R128_TransactionRoundTripRuntimeAndScripts_AreCanonical() { var i = LiveDirectorGroupProfile.CreateDefault(); var c = i with { ServerRevision = 1, SelectionCap = 96 }; var h = new LiveDirectorGroupHistory(i); var cmd = new LiveDirectorGroupCommand(Guid.NewGuid(), 1, "test:r128", 0, "gm:karen", NetworkRole.GameMaster, false, c); Assert.False(h.Execute(cmd).Applied); Assert.True(h.Execute(cmd with { Apply = true }).Applied); Assert.Equal(i, h.Undo("gm:karen", NetworkRole.GameMaster).Profile); Assert.Equal(c, h.Redo("gm:karen", NetworkRole.GameMaster).Profile); var s = new LiveDirectorGroupStore(); Assert.Equal(s.Serialize(c), s.Serialize(s.Deserialize(s.Serialize(c)))); Assert.Empty(LiveDirectorGroupRuntimeAdapter.Resolve(null, false).Diagnostics); Assert.Equal("LIVE_GROUP_REQUIRED_MISSING", Assert.Single(LiveDirectorGroupRuntimeAdapter.Resolve(null, true).Diagnostics).Code); Assert.True(new LiveDirectorGroupScriptService(i).Read(new(i.Id, 1)).Lasso); }
    [Fact] public void R128_InvalidPolicyPermissionAndRevision_AreLocalized() { var i = LiveDirectorGroupProfile.CreateDefault(); var invalid = i with { ServerRevision = 1, SelectionCap = 0 }; Assert.Contains(LiveDirectorGroupValidator.Validate(invalid), x => x.Code == "LIVE_SELECTION_POLICY_INVALID"); var r = new LiveDirectorGroupHistory(i).Execute(new(Guid.NewGuid(), 1, "test:r128", 9, "player", NetworkRole.Player, true, invalid)); Assert.Contains(r.Diagnostics, x => x.Code == "LIVE_GROUP_PERMISSION_DENIED"); Assert.Contains(r.Diagnostics, x => x.Code == "LIVE_GROUP_REVISION_STALE"); }
}
